10:   // don't slice args for v8 optimizations
11:   var len = arguments.length - 1;
12:   for (var i = 0; i < len; i++) {
13:     var obj = arguments[i + 1];
14:     if (isObject(obj)) {
15:       forOwn(obj, copy, o);
16:     }
17:   }
